export function adjacentGridDivision(
  current: number,
  direction: 'narrow' | 'widen',
): number | null {
  const index = GRID_DIVISIONS_SECONDS.findIndex((step) => step === current);
  if (index < 0) {
    return null;
  }
  return GRID_DIVISIONS_SECONDS[direction === 'narrow' ? index + 1 : index - 1] ?? null;
}
